package com.optarena.app

data class ProcResult(val key: String, val payload: Int, val processedAt: Long)
private data class Seen(val result: ProcResult, val recordedAt: Long)

class Processor(private val window: Long) {
    val effects = mutableListOf<Pair<String, Int>>()
    private val seen = HashMap<String, Seen>()

    fun process(key: String, payload: Int, now: Long): ProcResult {
        seen[key]?.let { cached ->
            if (now - cached.recordedAt < window) {
                return cached.result
            }
        }
        effects.add(key to payload)
        val result = ProcResult(key, payload, now)
        seen[key] = Seen(result, now)
        return result
    }
}

