package com.optarena.app

import org.junit.jupiter.api.Assertions.assertEquals
import org.junit.jupiter.api.Test

class ProcessorTest {
    @Test
    fun duplicateKeyWithinWindowNotReexecuted() {
        val p = Processor(10)
        val first = p.process("order-1", 5, 0)
        val second = p.process("order-1", 999, 5)
        assertEquals(first, second)
        assertEquals(1, p.effects.size)
    }

    @Test
    fun differentKeysBothExecute() {
        val p = Processor(10)
        p.process("a", 1, 0)
        p.process("b", 2, 0)
        assertEquals(2, p.effects.size)
    }

    @Test
    fun reexecutesAfterWindowExpires() {
        val p = Processor(10)
        p.process("order-1", 5, 0)
        p.process("order-1", 5, 9)
        assertEquals(1, p.effects.size)
        p.process("order-1", 7, 10)
        assertEquals(2, p.effects.size)
        assertEquals(7, p.effects[1].second)
    }
}
